<?php declare(strict_types=1);use App\Core\Database\Database;/** @var Database $db */$db=$app->make(Database::class);$tables=$db->execute("SELECT COUNT(*) n FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN('supplier_invoices','supplier_invoice_lines')")->fetch_assoc();if((int)$tables['n']!==2)throw new RuntimeException('Supplier invoice tables missing.');$permissions=$db->execute("SELECT COUNT(*) n FROM permissions WHERE module='supplier_invoices'")->fetch_assoc();if((int)$permissions['n']!==5)throw new RuntimeException('Supplier invoice permissions missing.');$assigned=$db->execute("SELECT COUNT(*) n FROM role_permissions rp JOIN roles r ON r.id=rp.role_id JOIN permissions p ON p.id=rp.permission_id WHERE r.code='super_admin' AND p.module='supplier_invoices'")->fetch_assoc();if((int)$assigned['n']!==5)throw new RuntimeException('Supplier invoice permissions not assigned.');
